def _manifest_identity(manifest: SourcingManifest) -> tuple[SourceKind, str, str]:
    canonical_url = str(manifest.canonical_url).rstrip("/")
    kind = manifest.source_kind
    if kind is None:
        host = (urlsplit(canonical_url).hostname or "").casefold()
        kind = {
            "github.com": SourceKind.GITHUB,
            "zenodo.org": SourceKind.ZENODO,
            "www.zenodo.org": SourceKind.ZENODO,
            "huggingface.co": SourceKind.HUGGING_FACE,
        }.get(host)
    if kind is None:
        raise ValueError("Approved manifest does not identify a supported source provider")
    revision = manifest.source_revision
    if revision is None and manifest.revision:
        prefix = f"{kind.value}:"
        revision = next(
            (
                value.removeprefix(prefix)
                for value in manifest.revision.split(";")
                if value.startswith(prefix)
            ),
            None,
        )
    if not revision:
        raise ValueError("Approved manifest does not contain an immutable source revision")
    return kind, canonical_url, revision


class ApprovedSourceStore:
    def __init__(self, path: Path):
        path.parent.mkdir(parents=True, exist_ok=True)
        self.connection = sqlite3.connect(path, check_same_thread=False, isolation_level=None)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA journal_mode=WAL")
        self.connection.execute("PRAGMA foreign_keys=ON")
        self.connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS approved_sources (
                approved_source_id TEXT PRIMARY KEY,
                source_kind TEXT NOT NULL,
                        approved_source_id,
                        kind.value,
                        canonical_url,
                        revision,
                        manifest.name,
                        manifest_json,
                        manifest_sha256,
                        approved_at,
                        approved_at,
                    ),
                )
                event_cursor = self.connection.execute(
                    """
                    INSERT OR IGNORE INTO approval_events VALUES (?, ?, ?, ?, ?, ?)
                    """,
                    (
                        approved_source_id,
                        manifest.run_id,
                        manifest.candidate_id,
                        manifest_json,
                        manifest_sha256,
                        approved_at,
                    ),
                )
                if restore_deleted and event_cursor.rowcount:
                    self.connection.execute(
                        """
                        UPDATE approved_sources SET deleted_at = NULL
                        WHERE approved_source_id = ?
                        """,
                        (approved_source_id,),
                    )
                self.connection.execute("COMMIT")
            except Exception:
                self.connection.execute("ROLLBACK")
                raise
        return approved_source_id

from __future__ import annotations

import argparse
import os
import time
from pathlib import Path

from .archive import SafeArchiveExtractor
from .dispatch import SpecializedDispatcher
from .inventory import ResourceInventory
from .jobs import IngestionJobStore
from .onboarding import IngestionOnboardingCoordinator, OnboardingWorker
from .providers import ProviderAcquirer
from .service import HttpApprovedSourceResolver
from .worker import AcquisitionWorker


def main() -> int:
    parser = argparse.ArgumentParser(description="Acquire queued approved dataset assets")
    parser.add_argument("--once", action="store_true", help="Process at most one queued job")
    parser.add_argument("--poll-seconds", type=float, default=2.0)
    args = parser.parse_args()
    if args.poll_seconds <= 0:
        parser.error("--poll-seconds must be positive")

    data_dir = Path(os.environ.get("INGESTION_DATA_DIR", "var/ingestion"))
    jobs = IngestionJobStore(data_dir / "ingestions.sqlite3")
    resolver = HttpApprovedSourceResolver(
        os.environ.get("INGESTION_SOURCING_API_URL", "http://127.0.0.1:8001")
    )
    acquirer = ProviderAcquirer(
        data_dir / "cache",
        github_token=os.environ.get("GITHUB_TOKEN"),
        hugging_face_token=os.environ.get("HF_TOKEN"),
    )
    dispatcher = SpecializedDispatcher(
        cache_dir=data_dir / "cache",
        registry_root=data_dir / "timef",
    )
    onboarding = IngestionOnboardingCoordinator(data_dir, jobs)
    worker = AcquisitionWorker(
        jobs,
        resolver,
        acquirer,
        extractor=SafeArchiveExtractor(data_dir / "cache"),
        inventory=ResourceInventory(),
        dispatcher=dispatcher,
        onboarding=onboarding,
    )
    onboarder = OnboardingWorker(onboarding)
    try:
        worker.recover_interrupted()
        onboarder.recover_interrupted()
        while True:
            processed = worker.run_once() or onboarder.run_once()
            if args.once:
                return 0
            if processed is None:
                time.sleep(args.poll_seconds)
    except KeyboardInterrupt:
        return 0
    finally:
        acquirer.close()
        resolver.close()
        jobs.close()


if __name__ == "__main__":
    raise SystemExit(main())
